import{_ as n,C as i,o as e,c as s,a2 as o,b as d,w as a,a as l,E as c,a3 as m}from"./chunks/framework.XaTYfhfj.js";const C=JSON.parse('{"title":"14.3 Networking, Protocols & Inter-Service Communication","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.3-networking-and-communication.md","filePath":"system-design/14.3-networking-and-communication.md"}'),h={name:"system-design/14.3-networking-and-communication.md"};function u(p,t,g,b,w,P){const r=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=o('<h1 id="_14-3-networking-protocols-inter-service-communication" tabindex="-1">14.3 Networking, Protocols &amp; Inter-Service Communication <a class="header-anchor" href="#_14-3-networking-protocols-inter-service-communication" aria-label="Permalink to &quot;14.3 Networking, Protocols &amp; Inter-Service Communication&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Networking in distributed systems governs how data travels across the physical and logical boundaries between user browsers, edge gateways, internal services, and cloud databases. It defines protocol choices, transport layers, encryption handshakes, and caching proxies.</p><hr><h2 id="_2-truthguard-network-topography-protocols" tabindex="-1">2. TruthGuard Network Topography &amp; Protocols <a class="header-anchor" href="#_2-truthguard-network-topography-protocols" aria-label="Permalink to &quot;2. TruthGuard Network Topography &amp; Protocols&quot;">​</a></h2>',5)),(e(),d(m,null,{default:a(()=>[c(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Client%5BBrowser%20Client%5D%20--%3E%7CHTTPS%20%2F%20TLS%201.3%20HTTP%2F2%7C%20CDN%5BCloudflare%20Global%20CDN%5D%0A%20%20%20%20CDN%20--%3E%7CTCP%20%2F%20TLS%201.3%7C%20Gateway%5BKong%20API%20Gateway%5D%0A%20%20%20%20Gateway%20--%3E%7CZero-Copy%20Dispatch%7C%20EdgeWorker%5BDeno%20V8%20Edge%20Worker%5D%0A%20%20%20%20Gateway%20--%3E%7CConnection%20Pooler%7C%20Postgres%5B(Supabase%20PostgreSQL)%5D%0A%0A%20%20%20%20subgraph%20ClientLocalNetwork%20%5B%22Client%20Localhost%20Ports%22%5D%0A%20%20%20%20%20%20%20%20HubClient%5BHub%20%3A5173%5D%20-.-%3E%7CHEAD%20no-cors%7C%20CameraMod%5BCamera%20%3A5183%5D%0A%20%20%20%20%20%20%20%20HubClient%20-.-%3E%7CHEAD%20no-cors%7C%20TelecomMod%5BTelecom%20%3A5182%5D%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<h3 id="communication-protocols-applied" tabindex="-1">Communication Protocols Applied <a class="header-anchor" href="#communication-protocols-applied" aria-label="Permalink to &quot;Communication Protocols Applied&quot;">​</a></h3><ol><li><strong>HTTP/2 over TLS 1.3</strong>: Used for all communication between the browser and Supabase Cloud. Enables multiplexing multiple requests over a single TCP connection, eliminating head-of-line blocking.</li><li><strong>Client-Side Dynamic Port Discovery (<code>HEAD / no-cors</code>)</strong>: Implemented in [<code>FeatureEmbed.tsx:L59-74</code>](file:///Users/avishjain/avishjain9-repos/33-codealchemist/mainpage/src/pages/FeatureEmbed.tsx#L59-L74) to probe local micro-frontend instances without downloading payload bodies.</li><li><strong>Synchronous REST JSON</strong>: Edge Functions communicate via request-response JSON bodies adhering strictly to typed TypeScript interfaces.</li></ol><hr><h2 id="_3-protocol-comparison-matrix" tabindex="-1">3. Protocol Comparison Matrix <a class="header-anchor" href="#_3-protocol-comparison-matrix" aria-label="Permalink to &quot;3. Protocol Comparison Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Transport</th><th>Latency</th><th>Multiplexing</th><th>Browser Support</th><th>Use in TruthGuard</th></tr></thead><tbody><tr><td><strong>HTTP/2 (Chosen for APIs)</strong></td><td>TCP</td><td>Low (~30ms)</td><td>Yes (Streams)</td><td>Universal</td><td><strong>API &amp; Edge Invocations</strong></td></tr><tr><td><strong>HTTP/3 (QUIC)</strong></td><td>UDP</td><td>Ultra-Low (~15ms)</td><td>Yes (Independent)</td><td>Modern Browsers</td><td>Supported via Cloudflare CDN edge</td></tr><tr><td><strong>HTTP/1.1 (Local Dev)</strong></td><td>TCP</td><td>Moderate (~80ms)</td><td>No (Pipelining flawed)</td><td>Universal</td><td>Used for local Vite dev servers</td></tr><tr><td><strong>WebSockets</strong></td><td>TCP</td><td>Real-Time (&lt;5ms)</td><td>Bi-directional</td><td>Universal</td><td>Planned for multi-analyst live feeds</td></tr><tr><td><strong>gRPC (HTTP/2 Protobuf)</strong></td><td>TCP</td><td>Minimal (~10ms)</td><td>Binary Multiplex</td><td>Requires gRPC-Web</td><td>Overkill for JSON browser interfaces</td></tr></tbody></table><hr><h2 id="_4-what-breaks-under-extreme-network-load" tabindex="-1">4. What Breaks Under Extreme Network Load <a class="header-anchor" href="#_4-what-breaks-under-extreme-network-load" aria-label="Permalink to &quot;4. What Breaks Under Extreme Network Load&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Standard HTTP/2 multiplexing easily absorbs load without connection bottlenecks.</li><li><strong>At 100x Load</strong>: Cloudflare CDN absorbs static bundle traffic. Kong API gateway connection poolers become the constraint for database transactions.</li><li><strong>At 1,000x Load</strong>: TCP socket exhaustion at the database layer. Requires shifting from TCP-based pooling to stateless HTTP-based connection proxying.</li></ul><hr><h2 id="_5-30-second-spoken-interview-answer" tabindex="-1">5. 30-Second Spoken Interview Answer <a class="header-anchor" href="#_5-30-second-spoken-interview-answer" aria-label="Permalink to &quot;5. 30-Second Spoken Interview Answer&quot;">​</a></h2><blockquote><p>&quot;For networking, we use HTTP/2 over TLS 1.3 for all Supabase API and Edge Function traffic, taking full advantage of stream multiplexing to prevent head-of-line blocking.</p><p>Locally, our Hub uses a lightweight discovery mechanism issuing non-blocking HTTP HEAD requests with <code>no-cors</code> mode to probe micro-frontend ports from 5176 to 5200. This verifies socket connectivity in milliseconds without downloading redundant HTML or JavaScript assets.&quot;</p></blockquote>',11))])}const k=n(h,[["render",u]]);export{C as __pageData,k as default};
